ALTER TABLE public.library_events DROP CONSTRAINT library_events_type_check;
ALTER TABLE public.library_events ADD CONSTRAINT library_events_type_check CHECK(type IN ('type_change','palette_shift','theme_flip','layout_change','redesign','message_pivot','pricing_change','new_surface','stack_change','nav_change','imagery_shift','aesthetic_shift'));
CREATE VIEW public.library_ai_tag_history AS SELECT t.snapshot_id,t.domain,t.model,t.tags,t.created_at,s.captured_at,ls.sector FROM public.library_tags t JOIN public.library_snapshots s ON s.id=t.snapshot_id JOIN public.library_sites ls ON ls.domain=t.domain WHERE ls.active AND s.source='live' AND s.page_type='home' AND s.viewport='desktop';
GRANT SELECT ON public.library_ai_tag_history TO anon,authenticated;
CREATE VIEW public.library_tag_share AS WITH periods AS (SELECT 'current'::text period,NULL::timestamptz cutoff UNION ALL SELECT 'previous',now()-interval '28 days'), latest AS (SELECT DISTINCT ON(p.period,h.domain) p.period,h.* FROM periods p JOIN public.library_ai_tag_history h ON p.cutoff IS NULL OR h.captured_at<=p.cutoff ORDER BY p.period,h.domain,h.captured_at DESC,h.snapshot_id DESC), scoped AS (SELECT l.*,x.sector_group FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector)) x(sector_group)), totals AS (SELECT period,sector_group,count(*) sites FROM scoped GROUP BY period,sector_group), values AS (SELECT DISTINCT l.period,l.sector_group,l.domain,d.key dimension,v.value FROM scoped l CROSS JOIN LATERAL jsonb_each(l.tags) d CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(d.value)='array' THEN d.value WHEN jsonb_typeof(d.value)='string' THEN jsonb_build_array(d.value) ELSE '[]'::jsonb END) v(value) WHERE d.key<>'confidence'), counts AS (SELECT period,sector_group,dimension,value,count(*) n FROM values GROUP BY period,sector_group,dimension,value), keys AS(SELECT DISTINCT sector_group,dimension,value FROM counts) SELECT k.sector_group AS sector,k.dimension,k.value,coalesce(c.n,0) AS sites,t.sites AS tagged_sites,coalesce(c.n,0)::numeric/t.sites AS share,CASE WHEN pt.sites>0 THEN coalesce(pc.n,0)::numeric/pt.sites ELSE NULL END AS share_28d,CASE WHEN pt.sites>0 THEN (coalesce(c.n,0)::numeric/t.sites-coalesce(pc.n,0)::numeric/pt.sites)*100 ELSE NULL END AS delta_28d_pts FROM keys k JOIN totals t ON t.period='current' AND t.sector_group=k.sector_group LEFT JOIN counts c ON c.period='current' AND c.sector_group=k.sector_group AND c.dimension=k.dimension AND c.value=k.value LEFT JOIN totals pt ON pt.period='previous' AND pt.sector_group=k.sector_group LEFT JOIN counts pc ON pc.period='previous' AND pc.sector_group=k.sector_group AND pc.dimension=k.dimension AND pc.value=k.value;
GRANT SELECT ON public.library_tag_share TO anon,authenticated;
CREATE VIEW public.library_ai_extraction_history AS SELECT e.snapshot_id,e.domain,e.kind,e.model,e.data,e.created_at,s.captured_at,ls.sector FROM public.library_extractions e JOIN public.library_snapshots s ON s.id=e.snapshot_id JOIN public.library_sites ls ON ls.domain=e.domain WHERE ls.active AND s.source='live' AND s.viewport='desktop' AND s.page_type=e.kind;
GRANT SELECT ON public.library_ai_extraction_history TO anon,authenticated;
CREATE VIEW public.library_pricing_stats AS WITH latest AS(SELECT DISTINCT ON(domain) * FROM public.library_ai_extraction_history WHERE kind='pricing' ORDER BY domain,captured_at DESC,snapshot_id DESC),scoped AS(SELECT l.*,x.sector_group FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector))x(sector_group)) SELECT sector_group AS sector,data->>'currency' AS currency,count(*) AS sites_extracted,avg((coalesce((data->>'has_free_tier')::boolean,false))::integer)::numeric AS free_tier_share,avg((coalesce((data->>'has_trial')::boolean,false))::integer)::numeric AS trial_share,avg((coalesce((data->>'has_usage_based')::boolean,false))::integer)::numeric AS usage_based_share,avg((coalesce((data->>'has_ai_addon')::boolean,false))::integer)::numeric AS ai_addon_share,avg((coalesce((data->>'ai_credits_model')::boolean,false))::integer)::numeric AS credit_metering_share,percentile_cont(0.5) WITHIN GROUP(ORDER BY (data->>'cheapest_paid_monthly')::numeric) AS median_cheapest_paid_monthly,avg((EXISTS(SELECT 1 FROM jsonb_array_elements(data->'plans') p WHERE (p->>'is_enterprise_contact')::boolean))::integer)::numeric AS enterprise_contact_share FROM scoped GROUP BY sector_group,data->>'currency';
GRANT SELECT ON public.library_pricing_stats TO anon,authenticated;
CREATE VIEW public.library_changelog_stats AS WITH latest AS(SELECT DISTINCT ON(domain) * FROM public.library_ai_extraction_history WHERE kind='changelog' ORDER BY domain,captured_at DESC,snapshot_id DESC),scoped AS(SELECT l.*,x.sector_group FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector))x(sector_group)) SELECT sector_group AS sector,count(*) AS sites_extracted,percentile_cont(0.5) WITHIN GROUP(ORDER BY (data->>'entries_last_30d')::numeric) AS median_entries_last_30d,percentile_cont(0.5) WITHIN GROUP(ORDER BY (data->>'ai_share')::numeric) AS median_ai_share,avg((coalesce((data->>'latest_date')::date>=current_date-30,false))::integer)::numeric AS shipped_last_30d_share FROM scoped GROUP BY sector_group;
GRANT SELECT ON public.library_changelog_stats TO anon,authenticated;
CREATE VIEW public.library_feature_themes AS WITH periods AS(SELECT 'current'::text period,NULL::timestamptz cutoff UNION ALL SELECT 'previous',now()-interval '28 days'),latest AS(SELECT DISTINCT ON(p.period,h.domain) p.period,h.* FROM periods p JOIN public.library_ai_extraction_history h ON h.kind='product' AND (p.cutoff IS NULL OR h.captured_at<=p.cutoff) ORDER BY p.period,h.domain,h.captured_at DESC,h.snapshot_id DESC),scoped AS(SELECT l.*,x.sector_group FROM latest l CROSS JOIN LATERAL(VALUES('all'::text),(l.sector))x(sector_group)),totals AS(SELECT period,sector_group,count(*) sites FROM scoped GROUP BY period,sector_group),themes AS(SELECT DISTINCT l.period,l.sector_group,l.domain,f->>'theme' theme FROM scoped l CROSS JOIN LATERAL jsonb_array_elements(l.data->'features') f),counts AS(SELECT period,sector_group,theme,count(*) n FROM themes GROUP BY period,sector_group,theme),keys AS(SELECT DISTINCT sector_group,theme FROM counts) SELECT k.sector_group AS sector,k.theme,coalesce(c.n,0) AS sites,t.sites AS sites_extracted,coalesce(c.n,0)::numeric/t.sites AS share,CASE WHEN pt.sites>0 THEN coalesce(pc.n,0) ELSE NULL END AS sites_28d,CASE WHEN pt.sites>0 THEN coalesce(c.n,0)-coalesce(pc.n,0) ELSE NULL END AS change_28d,CASE WHEN pt.sites>0 THEN (coalesce(c.n,0)::numeric/t.sites-coalesce(pc.n,0)::numeric/pt.sites)*100 ELSE NULL END AS delta_28d_pts FROM keys k JOIN totals t ON t.period='current' AND t.sector_group=k.sector_group LEFT JOIN counts c ON c.period='current' AND c.sector_group=k.sector_group AND c.theme=k.theme LEFT JOIN totals pt ON pt.period='previous' AND pt.sector_group=k.sector_group LEFT JOIN counts pc ON pc.period='previous' AND pc.sector_group=k.sector_group AND pc.theme=k.theme;
GRANT SELECT ON public.library_feature_themes TO anon,authenticated;